"use client";
/* Tabby, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Tabby(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("tabby"); }, []);
  return React.createElement("piix-pal", { "pal": "tabby", ...piixAttrs(props) });
}

export default Tabby;
